 public sealed class CargoFxControlledProbeV21:MonoBehaviour {
  readonly List<CargoFxProbeCheckV21> checks=new List<CargoFxProbeCheckV21>();readonly List<CargoFxProbeCaptureV21> captures=new List<CargoFxProbeCaptureV21>();string manifestPath,output;Action<int> done;Shader shader;CargoFxProbeInputV21 input;CargoVisualDocumentV21 document;CargoAudioDocumentV21 audioDocument;CargoFxSourceEffectsV21 effects;CargoFxSourceCallbacksV21 sourceCallbacks;CargoFxFeedV21 feed;CargoFxViewV21 view;CargoAudioRuntimeV21 audioBank;GameObject root,cameraObject;Camera cameraProbe;CargoFxProbeReportV21 report;int epoch;
  public static string Sha(byte[] b){return CargoDirectorHashV21.Hash(b);}void Check(string n,bool v,string detail=""){checks.Add(new CargoFxProbeCheckV21{name=n,passed=v,detail=detail});}byte[] Read(CargoFilePinV21 p){var b=File.ReadAllBytes(p.path);if(Sha(b)!=p.sha256)throw new InvalidOperationException("Changed exact input "+p.path);return b;}T Load<T>(CargoFilePinV21 p){return JsonUtility.FromJson<T>(System.Text.Encoding.UTF8.GetString(Read(p)));}
  public void Begin(string manifest,string folder,Shader sourceShader,Action<int> complete){manifestPath=manifest;output=folder;shader=sourceShader;done=complete;StartCoroutine(Execute());}
  static string[] MissingPreparedMeshes(CargoVisualDocumentV21 doc,OutskirtsNpcMeshManifest manifest){var names=new HashSet<string>();foreach(var m in manifest.components)names.Add(m.id);var errors=new List<string>();foreach(var p in doc.particles)if(p.supported&&!String.IsNullOrEmpty(p.mesh)&&!names.Contains(p.mesh))errors.Add(p.key+" -> "+p.mesh);foreach(var m in doc.effectMeshes)if(!names.Contains(m.mesh))errors.Add("effect/"+m.effect+" -> "+m.mesh);return errors.ToArray();}
  void TypedJsonUtilityPreflight(CargoVisualBindingV21 corrected){var previous=Load<CargoVisualBindingV21>(input.regressionOriginalBinding);var oldDoc=Load<CargoVisualDocumentV21>(previous.document);var oldMeshes=Load<OutskirtsNpcMeshManifest>(previous.meshManifest);var bad=MissingPreparedMeshes(oldDoc,oldMeshes);Check("actual JsonUtility r1 reproduces exactly2 stale prepared-mesh links",bad.Length==2&&Array.Exists(bad,s=>s.StartsWith("Minor/ChainGateLight1 -> projected-minor-chaingatelight1"))&&Array.Exists(bad,s=>s.StartsWith("Minor/ChainGateLight2 -> projected-minor-chaingatelight2")),String.Join("; ",bad));var currentMeshes=Load<OutskirtsNpcMeshManifest>(corrected.meshManifest);var currentBad=MissingPreparedMeshes(document,currentMeshes);Check("actual JsonUtility r2 all particle/effect mesh links resolve",currentBad.Length==0,String.Join("; ",currentBad));Check("actual JsonUtility r2 retains42typed templates and6real components",document.particles.Length==42&&currentMeshes.components.Length==6);foreach(var key in new[]{"Minor/ChainGateLight1","Minor/ChainGateLight2"}){var p=Array.Find(document.particles,s=>s.key==key);var parsed=JsonUtility.FromJson<OutskirtsVisualParticle>(p.particleJson);Check("actual JsonUtility exact source dynamic plane "+key,p.supported&&String.IsNullOrEmpty(p.mesh)&&p.explicitBasisAdapter=="authored-fixedXY-unit-plane-source-only-Z-rotation-v21"&&parsed.particleType=="PT_3D_PLANE"&&parsed.billboardType=="BT_NONE"&&parsed.lifetime[0]==10000&&parsed.lifetime[1]==10000&&parsed.curves.Length>0);}}
  void Setup(){input=JsonUtility.FromJson<CargoFxProbeInputV21>(File.ReadAllText(manifestPath));var binding=Load<CargoVisualBindingV21>(input.binding);document=Load<CargoVisualDocumentV21>(binding.document);TypedJsonUtilityPreflight(binding);audioDocument=Load<CargoAudioDocumentV21>(input.audio);effects=Load<CargoFxSourceEffectsV21>(input.sourceEffects);sourceCallbacks=Load<CargoFxSourceCallbacksV21>(input.sourceCallbacks);feed=new CargoFxFeedV21(CargoFxFeedV21.ExactEffectsSha256,document.callbackBindings);root=new GameObject("Cargo actual source FX isolated root");root.layer=30;view=new CargoFxViewV21(feed,root.transform,shader);view.LoadBinding(input.binding.path,input.binding.sha256);audioBank=new CargoAudioRuntimeV21(root.transform);cameraObject=new GameObject("Cargo FX source component Camera");cameraProbe=cameraObject.AddComponent<Camera>();cameraProbe.enabled=false;cameraProbe.orthographic=true;cameraProbe.orthographicSize=216;cameraProbe.aspect=768f/432;cameraProbe.transform.position=new Vector3(0,180,-30);cameraProbe.nearClipPlane=.1f;cameraProbe.farClipPlane=100;cameraProbe.cullingMask=1<<30;cameraProbe.allowHDR=cameraProbe.allowMSAA=false;cameraProbe.clearFlags=CameraClearFlags.SolidColor;Check("all10 exact source definitions loaded",document.definitions.Length==10&&effects.definitions.Length==10);Check("8zero draw definitions unpainted",Array.FindAll(document.definitions,d=>!d.mainMeshRequired).Length==8);}
  float Move(string id,float age){var d=Array.Find(effects.definitions,q=>q.id==id);var a=d.samples[0];foreach(var b in d.samples){if(b.time>=age){float u=b.time>a.time?(age-a.time)/(b.time-a.time):0;return a.moveX+(b.moveX-a.moveX)*u;}a=b;}return a.moveX;}
  CargoLiveEffectV21 Fx(string id,int serial,float age,float x,float y,int facing=1,float angle=0){var d=Array.Find(effects.definitions,q=>q.id==id);return CargoFlightV21.ControlledSnapshot(id,CargoFxFeedV21.OwnerForEffect(id),serial,100,age,x,y,0,facing,angle,Move(id,age),d.lifetime,0);}
  void Request(CargoCallbackBindingV21 b,int seq,int owner,float age,float x,float y,float z=0){feed.SubmitObservedParticle(new CargoObservedParticleV21{bindingId=b.id,npc=b.npc,state=b.state,sourceInstructionsSha256=b.sourceInstructionsSha256,particleKey=b.particleKey,kind="spawn",sequence=seq,ownerSerial=owner,time=0,sourceLocalTime=b.particleKey=="Major/Wally9th_Armor_ChargeBall02"?.01f:2.1f,x=x,y=y,z=z,hasSourceLandY=true,landY=0});}
  void RenderCase(CargoFxCaseV21 c){cameraProbe.transform.position=new Vector3(0,c.scenario=="special-balls"?14:180,-30);feed.ResetRoom(++epoch,2);var live=new List<CargoLiveEffectV21>();if(c.scenario=="bee")live.Add(Fx(c.effect,1,c.age,-80,180,c.label.Contains("left")?-1:1));else if(c.scenario=="six-missiles"){for(int i=0;i<6;i++){var lane=sourceCallbacks.missileLanes[i];live.Add(Fx(c.effect,i+1,c.age,lane.originOffset[0],100+lane.originOffset[1],1,lane.rotationZ));}}else if(c.scenario=="special-balls"){for(int side=-1;side<=1;side+=2)live.Add(Fx(c.effect,side+2,c.age,side*196,14));}else{var d=Array.Find(effects.definitions,q=>q.id==c.effect);if(c.age<d.lifetime)live.Add(Fx(c.effect,1,c.age,0,160));}feed.SetFrame(c.age,live.ToArray());if(c.scenario=="six-missiles"){var b=Array.Find(document.callbackBindings,q=>q.particleKey=="Minor/Wally9th_MissileAttack02");for(int i=0;i<6;i++){var p=sourceCallbacks.missileLanes[i].originOffset;Request(b,i+1,i+1,c.age,p[0]+2.8f,100+p[1],p[2]-14);}}else if(c.scenario=="special-balls"){var bindings=Array.FindAll(document.callbackBindings,q=>q.particleKey=="Major/Wally9th_Armor_ChargeBall02");Check("both original special-ball literal sites",bindings.Length==2);Request(bindings[0],1,3,c.age,196,14);Request(bindings[1],2,1,c.age,-196,14);}else if(c.scenario=="controlled-hit"){feed.SubmitEffectEvent(new CargoEffectEventV21{sequence=1,serial=1,type=Array.Exists(document.effectParticles,q=>q.effect==c.effect&&q.eventType=="hit")?"hit":"spawn",effect=c.effect,npc=CargoFxFeedV21.OwnerForEffect(c.effect),time=0,x=0,y=160,hasSourceLandY=true,landY=0});}int beforeMain=view.CargoVisualMainMeshDrawFramesV21;view.Render();Check(c.label+" live sprites actually configured",view.CargoVisualVisibleSpritesV21>0,"visible="+view.CargoVisualVisibleSpritesV21);if(c.scenario=="bee")Check(c.label+" actual source negativeY in snapshot",live[0].y<180);if(c.scenario=="six-missiles")Check(c.label+" all6 real main meshes",view.CargoVisualMainMeshDrawFramesV21-beforeMain==6);var r=new CargoFxProbeCaptureV21{label=c.label,scenario=c.scenario,effect=c.effect,age=c.age,visible=view.CargoVisualVisibleSpritesV21,mainMeshFrames=view.CargoVisualMainMeshDrawFramesV21,held=view.CargoVisualHeldEventsV21,committedControlledEffects=live.ToArray(),cumulativeDrawnKinds=view.CargoVisualDrawnKindsV21,drawnKindsSemantics="drawnKinds/currentFrameRenderers are observed active SpriteRenderers for this frame; cumulativeDrawnKinds is historical component API across all prior frames",cameraPosition=new[]{cameraProbe.transform.position.x,cameraProbe.transform.position.y,cameraProbe.transform.position.z}};ObserveCurrentFrame(r);Capture(c.label,false,r);if(c.label=="source-fields-1"||c.label=="source-fields-7")Capture(c.label,false,r,true);captures.Add(r);}
  CargoFilePinV21 Save(string name,Texture2D t){string p=Path.Combine(output,name);File.WriteAllBytes(p,ImageConversion.EncodeToPNG(t));return new CargoFilePinV21{path=p,sha256=Sha(File.ReadAllBytes(p))};}
  void ObserveCurrentFrame(CargoFxProbeCaptureV21 row){var observed=new List<CargoFxRendererObservationV21>();var kinds=new HashSet<string>();foreach(var s in view.CargoVisualSpritesV21){if(!s||!s.gameObject.activeInHierarchy||!s.enabled||!s.sprite)continue;var m=s.sharedMaterial;var bounds=s.bounds;observed.Add(new CargoFxRendererObservationV21{name=s.gameObject.name,spriteName=s.sprite.name,textureName=s.sprite.texture.name,sourceBlend=m.GetInt("_SrcBlend"),destinationBlend=m.GetInt("_DstBlend"),worldBounds=new[]{bounds.min.x,bounds.min.y,bounds.max.x,bounds.max.y}});string name=s.gameObject.name;if(name.StartsWith("Original Cargo mesh "))kinds.Add("mesh/"+name.Substring("Original Cargo mesh ".Length));else if(name.StartsWith("Original Cargo particle "))kinds.Add(name.Substring("Original Cargo particle ".Length));else throw new InvalidOperationException("Unidentified current renderer "+name);}row.currentFrameRenderers=observed.ToArray();row.drawnKinds=new string[kinds.Count];kinds.CopyTo(row.drawnKinds);Array.Sort(row.drawnKinds,StringComparer.Ordinal);Check(row.label+" current active renderer count matches actual frame",observed.Count==view.CargoVisualVisibleSpritesV21,"actual="+observed.Count);}
  void Capture(string label,bool expectBlank,CargoFxProbeCaptureV21 row=null,bool opaqueGray=false){
   var rt=new RenderTexture(768,432,0,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Default);rt.antiAliasing=1;rt.filterMode=FilterMode.Point;rt.Create();var old=RenderTexture.active;cameraProbe.targetTexture=rt;cameraProbe.backgroundColor=opaqueGray?new Color(.24f,.28f,.32f,1):Color.clear;cameraProbe.Render();report.cameraRenderCalls++;if(opaqueGray)report.opaqueGrayDiagnosticRenderCalls++;report.actualCameraRenderExecuted=true;RenderTexture.active=rt;var texture=new Texture2D(768,432,TextureFormat.RGBA32,false,true);texture.ReadPixels(new Rect(0,0,768,432),0,0);texture.Apply(false,false);var pixels=texture.GetPixels32();int l=768,b=432,r=0,top=0,n=0;
   if(!opaqueGray){for(int y=0;y<432;y++)for(int x=0;x<768;x++)if(pixels[y*768+x].a>0){n++;l=Math.Min(l,x);b=Math.Min(b,y);r=Math.Max(r,x+1);top=Math.Max(top,y+1);}Check(label+(expectBlank?" actual alpha blank":" actual visible GPU pixels"),expectBlank?n==0:n>0,"alphaPixels="+n);if(row!=null){row.actualAlphaBoundsTopDown=new[]{l,432-top,r,432-b};row.actualMinimumAlphaMargin=Math.Min(Math.Min(l,768-r),Math.Min(b,432-top));Check(label+" complete actual alpha extent has at least6px camera margin",n>0&&row.actualMinimumAlphaMargin>=6,"margin="+row.actualMinimumAlphaMargin);l=Math.Max(0,l-6);b=Math.Max(0,b-6);r=Math.Min(768,r+6);top=Math.Min(432,top+6);row.cropTopDown=new[]{l,432-top,r,432-b};}}
   else{if(row==null||row.cropTopDown==null)throw new InvalidOperationException("Gray diagnostic needs matching transparent extent");l=row.cropTopDown[0];top=432-row.cropTopDown[1];r=row.cropTopDown[2];b=432-row.cropTopDown[3];row.opaqueGrayRGBA=new[]{.24f,.28f,.32f,1f};Check(label+" opaque diagnostic uses same camera and sprites",view.CargoVisualVisibleSpritesV21==row.visible&&cameraProbe.orthographicSize==216);}
   var file=Save(label+(opaqueGray?"-actual-opaque-gray-native.png":"-actual-native.png"),texture);if(row!=null){if(opaqueGray)row.opaqueGrayNative=file;else row.actualNative=file;int w=(r-l)*4,h=(top-b)*4;var zoom=new Texture2D(w,h,TextureFormat.RGBA32,false,true);var a=new Color32[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++)a[y*w+x]=pixels[(b+y/4)*768+l+x/4];zoom.SetPixels32(a);zoom.Apply(false,false);var enlarged=Save(label+(opaqueGray?"-actual-opaque-gray-complete-nearest4x.png":"-actual-complete-nearest4x.png"),zoom);if(opaqueGray)row.opaqueGrayComplete4x=enlarged;else row.actualComplete4x=enlarged;Destroy(zoom);}Destroy(texture);cameraProbe.targetTexture=null;RenderTexture.active=old;rt.Release();Destroy(rt);
  }
  CargoSoundPacketV21 SoundPacket(CargoStateSoundTrackV21 t,CargoTimedSoundV21 c,long serial){return new CargoSoundPacketV21{roomEpoch=100,serial=serial,entrySerial=serial,actorSerial=100,kind="state",npc=t.npc,state=t.state,eventId=c.id,sound=c.sound,sourceField=c.sourceField,sourceName=c.sourceName,sourceTime=c.sourceTime,localTime=c.candidateTime,time=c.candidateTime};}
  IEnumerator Execute(){report=new CargoFxProbeReportV21{inputManifestSha256=Sha(File.ReadAllBytes(manifestPath)),unityVersion=Application.unityVersion,device=SystemInfo.graphicsDeviceName,colorSpace=QualitySettings.activeColorSpace.ToString()};bool setup=false;try{Setup();setup=true;}catch(Exception e){report.error=e.ToString();Check("setup",false,e.ToString());}if(setup){var decoder=audioBank.Load(input.audio.path,input.audio.sha256);while(true){bool more=false;object pending=null;try{more=decoder.MoveNext();if(more)pending=decoder.Current;}catch(Exception e){report.error=e.ToString();Check("audio decode coroutine completed",false,e.ToString());break;}if(!more)break;yield return pending;}try{Check("all64 original audioBank containers actually decoded",audioBank.DecodedClips==64,audioBank.LastError);report.decodedOriginalAudioClips=audioBank.DecodedClips;foreach(var c in input.captures)RenderCase(c);audioBank.ResetRoom(100);var track=Array.Find(audioDocument.stateTracks,t=>t.npc=="NUI_BEE_NASOD"&&t.state=="BEE_NASOD_ATTACK_A");var cue=track.events[0];audioBank.Consume(SoundPacket(track,cue,1),false);Check("real AudioSource playback API called",audioBank.PlaybackCalls==1);audioBank.Consume(SoundPacket(track,cue,2),true);Check("muted packet consumed without replay",audioBank.MutedConsumed==1&&audioBank.PlaybackCalls==1);audioBank.ResetRoom(101);Check("audioBank room reset stops scoped voices",audioBank.ActiveVoices==0);report.actualAudioSourcePlaybackCalls=audioBank.PlaybackCalls;feed.ResetRoom(++epoch,3);feed.SetFrame(0,new CargoLiveEffectV21[0]);view.Render();Capture("room-reset",true);view.ReleaseRoom();Check("room release clears pool/instances",view.CargoVisualPoolCountV21==0&&view.CargoVisualLiveSequencesV21==0);view.Dispose();view=null;audioBank.Dispose();audioBank=null;}catch(Exception e){report.error=e.ToString();Check("component execution completed",false,e.ToString());}}yield return null;yield return null;try{if(cameraProbe)Capture("disposed",true);Check("source binding unchanged",Sha(File.ReadAllBytes(input.binding.path))==input.binding.sha256);Check("audioBank manifest unchanged",Sha(File.ReadAllBytes(input.audio.path))==input.audio.sha256);}catch(Exception e){report.error=(report.error??"")+e;Check("post-dispose evidence",false,e.ToString());}if(view!=null)view.Dispose();if(audioBank!=null)audioBank.Dispose();report.checks=checks.ToArray();report.captures=captures.ToArray();bool passed=true;foreach(var c in checks)if(!c.passed)passed=false;report.mechanicalPassed=passed;File.WriteAllText(Path.Combine(output,"report.json"),JsonUtility.ToJson(report,true));if(root)Destroy(root);if(cameraObject)Destroy(cameraObject);if(done!=null)done(passed?0:1);}
 }
